const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const brazil = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017").filter(ee.Filter.eq('country_na', 'Brazil'));
  const geometry = brazil.geometry();

  const startDate2007 = '2007-01-01';
  const endDate2007 = '2007-12-31';

  const startDate2019 = '2019-01-01';
  const endDate2019 = '2019-12-31';

  // 2. Data Acquisition
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML');

  const fires2007 = fireCollection
    .filterDate(startDate2007, endDate2007)
    .filterBounds(geometry);

  const fires2019 = fireCollection
    .filterDate(startDate2019, endDate2019)
    .filterBounds(geometry);

  // 3. Calculation & Validation
  const count2007 = fires2007.size().getInfo();
  const count2019 = fires2019.size().getInfo();

  // Check for C1: Empty Collection
  if (count2007 === 0 || count2019 === 0) {
    console.log(`Fire Detections in 2007: ${count2007}`);
    console.log(`Fire Detections in 2019: ${count2019}`);
    console.log("Evidence: No fire detections found for one or both years.");
    console.log("C1");
    return;
  }

  // Note: C2/C3 are less likely here as we are just counting features, not processing pixels.
  // The size() check effectively covers the main failure modes for this type of data.

  // 4. Final Comparison and Output
  console.log(`Fire Detections in 2007: ${count2007}`);
  console.log(`Fire Detections in 2019: ${count2019}`);

  if (count2019 < count2007) {
    console.log("Evidence: The number of fire detections in 2019 was less than in 2007.");
    console.log("A");
  } else {
    console.log("Evidence: The number of fire detections in 2019 was not less than in 2007.");
    console.log("B");
  }
}

